ALLOWED_PRIORITIES = ("low", "normal", "high")
DEFAULT_PRIORITY = "normal"


def _validated_priority(value):
    if value not in ALLOWED_PRIORITIES:
        raise ValueError(f"priority must be one of {list(ALLOWED_PRIORITIES)}, got {value!r}")
    return value


@dataclass
class Task:
    id: int
    title: str
    done: bool = False
    priority: str = DEFAULT_PRIORITY

    def validate(self):
        if not self.title.strip():
            raise ValueError("title must not be empty")
        _validated_priority(self.priority)
